pairs.append(p2)
code='''def transform(grid):
    n = len(grid)
    colors = {v for row in grid for v in row if v != 7}
    for color in colors:
        cells = {(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == color}
        if any(r == c for r, c in cells):
            return [[color if r == c else 7 for c in range(n)] for r in range(n)]
        if any(r + c == n - 1 for r, c in cells):
            return [[color if r + c == n - 1 else 7 for c in range(n)] for r in range(n)]
    return [[7] * n for _ in range(n)]
'''
